  const others=items.filter((_,k)=>k!==i&&k!==j);
  const x=exprs[i],y=exprs[j], rest=exprs.filter((_,k)=>k!==i&&k!==j);
  const candidates=[
   [a*d+c*b,b*d,`(${x}+${y})`],
   [a*d-c*b,b*d,`(${x}-${y})`],
   [c*b-a*d,b*d,`(${y}-${x})`],
   [a*c,b*d,`(${x}*${y})`],
   ...(c?[ [a*d,b*c,`(${x}/${y})`]]:[]),
   ...(a?[ [c*b,d*a,`(${y}/${x})`]]:[])
  ];
  for(const [nn,dd,e] of candidates){
   if(!dd)continue;
   const [n,dn]=norm(nn,dd);
