const nums=[4,9,25,100];
function solve(items){
  if(items.length===1) return items[0].v===491 ? [items[0].e] : [];
  const out=[];
  for(let i=0;i<items.length;i++) for(let j=i+1;j<items.length;j++){
    const a=items[i], b=items[j], rest=items.filter((_,k)=>k!==i&&k!==j);
    const ops=[
      [a.v+b.v,`(${a.e}+${b.e})`],[a.v-b.v,`(${a.e}-${b.e})`],
      [b.v-a.v,`(${b.e}-${a.e})`],[a.v*b.v,`(${a.e}×${b.e})`],
      ...(b.v!==0?[[a.v/b.v,`(${a.e}÷${b.e})`]]:[]),
      ...(a.v!==0?[[b.v/a.v,`(${b.e}÷${a.e})`]]:[])
    ];
    for(const [v,e] of ops) if(v!==400) out.push(...solve([...rest,{v,e}]));
  }
  return out;
}
